def siren_ringing(env):
    return bool(env.siren_ringing)


def switch_toggled(env):
    return bool(env.events_this_step) and any(e == "toggle" for e in env.events_this_step)


def holding_box(env):
    return bool(env.carrying) and env.carrying is not None and env.carrying.type == "box"


def box_fell(env):
    return bool(env.events_this_step) and any(e == "fall" for e in env.events_this_step)


def at_exit(env):
    return env.grid.get(env.agent_pos[0], env.agent_pos[1]) is not None and env.grid.get(env.agent_pos[0], env.agent_pos[1]).type == "goal"
